// 프런트: PG SDK 가 카드 입력을 처리하고 토큰을 준다
const { token } = await pg.createToken(cardElement);  // 카드는 PG 로 직접
// 내 서버로는 토큰만 보낸다 (카드 번호는 절대 안 보냄)
await fetch('/pay', { method: 'POST', body: JSON.stringify({ token, 주문id }) });

// 서버: 토큰 + '서버가 정한 금액'으로 결제 (금액은 주문에서 다시 계산, 4장)
app.post('/pay', async (req, res) => {
  const 금액 = await 주문금액계산(req.body.주문id);   // 클라이언트 금액 X
  await pg.charge({ source: req.body.token, amount: 금액 });
  // 카드 원본은 내 서버에 없음 → PCI 범위 밖
});

// ❌ 클라이언트가 보낸 금액을 믿음. 조작되면 100원 결제
app.post('/pay', async (req, res) => {
  await pg.charge({ amount: req.body.금액, ... });  // 위험! 조작 가능
});

// ✅ 서버가 주문에서 금액을 다시 계산
app.post('/pay', async (req, res) => {
  const 주문 = await db.주문.get(req.body.주문id);
  let 금액 = 0;
  for (const item of 주문.항목) {
    const 상품 = await db.상품.get(item.상품id);      // 권위 있는 가격
    금액 += 상품.가격 * item.수량;                      // 서버가 계산
  }
  await pg.charge({ amount: 금액, ... });  // 클라이언트 금액은 무시
});
